candidates.raw:
    if (c == NULL || orth == NULL || det == NULL) {
        *orth = INFINITY;
        *det = 0.0;
        return ADCS_E_NULL;
    }

    size_t i, j;
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            if (!isfinite(c->m[i][j])) {
                *orth = INFINITY;
                *det = 0.0;
                return ADCS_E_NOT_FINITE;
            }
        }
    }

    adcs_mat3_t ct = adcs_mat3_transpose(c);
    adcs_mat3_t p = adcs_mat3_mul(c, &ct);

    double sum_sq = 0.0;
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            double val = p.m[i][j];
            if (i == j) {
                val -= 1.0;
            }
            sum_sq += val * val;
        }
    }
    *orth = sqrt(sum_sq);

    *det = adcs_mat3_det(c);

    return ADCS_OK;
}

